-- Seed data referensi: 5 jenis_kegiatan + kelompok baku (dari analisis 9 Sprin nyata,
-- diambil dari halaman Jenis Kegiatan mockup) + dasar_hukum_baku (baru ada untuk
-- Pengamanan Unjuk Rasa -- 4 jenis lain belum punya teks dasar hukum baku yang
-- terverifikasi, menyusul kalau datanya didapat).
-- Aman dijalankan ulang: ON CONFLICT mengabaikan baris yang sudah ada.

insert into public.jenis_kegiatan (nama, kode_klasifikasi, kategori, perkiraan_durasi_jam, wajib_isi_durasi_manual)
select x.nama, x.kode_klasifikasi, x.kategori::kategori_kegiatan, x.perkiraan_durasi_jam, x.wajib_isi_durasi_manual
from jsonb_to_recordset('[{"nama": "KEGIATAN RUTIN YANG DITINGKATKAN", "kode_klasifikasi": "PAM.1.3.2.", "kategori": "KRYD", "perkiraan_durasi_jam": 4, "wajib_isi_durasi_manual": false}, {"nama": "PENGAMANAN VIP/VVIP", "kode_klasifikasi": "PAM.2.2.", "kategori": "PAM_VIP", "perkiraan_durasi_jam": 6, "wajib_isi_durasi_manual": false}, {"nama": "PENGAMANAN UNJUK RASA", "kode_klasifikasi": "PAM.3.2.", "kategori": "UNRAS", "perkiraan_durasi_jam": 8, "wajib_isi_durasi_manual": false}, {"nama": "OPERASI KEPOLISIAN KEWILAYAHAN", "kode_klasifikasi": "OPS.1.3.", "kategori": "OPERASI", "perkiraan_durasi_jam": null, "wajib_isi_durasi_manual": true}, {"nama": "OPERASI KEPOLISIAN HARI BESAR", "kode_klasifikasi": "OPS.1.2.3.", "kategori": "OPERASI", "perkiraan_durasi_jam": null, "wajib_isi_durasi_manual": true}]'::jsonb) as x(
  nama text, kode_klasifikasi text, kategori text, perkiraan_durasi_jam int, wajib_isi_durasi_manual boolean
)
on conflict (nama) do nothing;

