  where existing.jenis_kegiatan_id = jk.id and existing.nama_kelompok = x.nama_kelompok
);

insert into public.dasar_hukum_baku (teks, jenis)
select x.teks, x.jenis::jenis_dasar_hukum
from jsonb_to_recordset('[{"teks": "Undang-Undang Nomor 5 Tahun 2026 tentang perubahan ketiga atas Undang-Undang Nomor 2 Tahun 2002 tentang Kepolisian Negara Republik Indonesia;", "jenis": "UU"}, {"teks": "Perkap Nomor 1 Tahun 2009 tentang Penggunaan Kekuatan dalam Tindakan Kepolisian;", "jenis": "PERKAP"}, {"teks": "Peraturan Kepala Kepolisian Negara Republik Indonesia Nomor 8 Tahun 2021 tentang Perubahan atas Perkap Nomor 1 Tahun 2019 tentang Sistem, Manajemen dan Standar Keberhasilan Operasional Polri;", "jenis": "PERKAP"}, {"teks": "Rengiat Polres Cimahi T.A. 2026.", "jenis": "PERATURAN_LAIN"}]'::jsonb) as x(teks text, jenis text)
where not exists (select 1 from public.dasar_hukum_baku existing where existing.teks = x.teks);
